import {chapters,chapterById,sceneById,policyNames,endingCatalog,endingTitle} from './v4-game.mjs';
import {worldLabels,initialWorld,signals,moodLabel} from './v4-world.mjs';
import {liveStrip,impactPanel,reactionPanel,developing,crewRoster} from './v4-ui.mjs';
import {freshRun,initialApp,restoreApp,simulate,validAnswer,commit,continueRun,advanceChapter,rewind,endingStory,exportJournal} from './v4-engine.mjs';
const root=document.querySelector('#app'),dialog=document.querySelector('#info-dialog'),STORAGE='team12-next-shift-v4';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const content=(x,w)=>typeof x==='function'?x(w):x;
let storage=true,app,screen='home',draft=null,error='',rewindTarget=null;
try{app=restoreApp(localStorage.getItem(STORAGE));}catch{app=initialApp();storage=false;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(app));}catch{storage=false;}}
const arrow='<span aria-hidden="true">↗</span>';
function portrait(id,size=''){const s=chapterById(id);return `<div class="portrait ${id} ${size}" aria-hidden="true"><div class="portrait-glow"></div><div class="portrait-head"><i class="hair"></i><i class="eyes"></i></div><div class="portrait-body"></div><span class="portrait-initial">${s.person[0]}</span></div>`;}
function header(){return `<header class="site-header"><button class="brand" data-action="home" aria-label="The Next Shift home"><span class="brand-symbol" aria-hidden="true">N<span>↗</span></span><span>THE NEXT SHIFT<span class="brand-sub">A PLAYABLE WAREHOUSE STORY · V4</span></span></button><nav aria-label="Main navigation"><button data-action="endings">Ending collection</button><button data-action="policy">The policy ${arrow}</button><button class="reset-nav" data-action="how">How to play</button></nav></header>`;}
function footer(){return `<footer class="site-footer"><span>TEAM 12 <span class="footer-dash">/</span> ETHICS & POLICY ISSUES IN COMPUTING</span><button data-action="sources">Sources & method ${arrow}</button><button data-action="reset">Reset this game</button><span>${storage?'Progress stays in this browser':'Progress is available for this visit only'}</span></footer>`;}
function warehouse(w={},chapter='tim',interactive=false){
  w=w.people?w:{...initialWorld(),...w};
  const monitor=chapter==='tim'?w.tMonitor&&w.tMonitor!=='off':chapter==='tom'?w.mCollect||w.mNewMonitoring:false;
  const stopped=chapter==='priya'&&w.pIsolate&&!w.pValidated,l=worldLabels(w,chapter);
  return `<div class="world-frame"><div data-mood="${w.people[chapter].mood}" data-pressure="${w.queue}" class="warehouse game-warehouse ${chapter} ${stopped?'world-stopped':''} ${w.tBreak?'world-break':''} ${w.tHelp?'world-help':''} ${monitor?'world-monitor':''} ${w.tQueue==='blocked'?'world-queue':''}" role="img" aria-label="Illustrated warehouse. ${esc(l.worker)}. ${esc(l.operations)}. ${esc(l.data)}."><div class="floor-grid"></div><div class="warehouse-label"><span class="live-dot"></span> BAMAZON · FICTIONAL WAREHOUSE</div><div class="zone-label z-one">PICKING / A</div><div class="zone-label z-two">HANDOFF / B</div><div class="shelf shelf-one">${'<i></i>'.repeat(9)}</div><div class="shelf shelf-two">${'<i></i>'.repeat(9)}</div><div class="shelf shelf-three">${'<i></i>'.repeat(6)}</div><div class="route route-one"></div><div class="route route-two"></div><div class="robot bot-one"><span></span><i></i><b>01</b></div><div class="robot bot-two"><span></span><i></i><b>02</b></div><div class="worker worker-one"><i></i><b>${chapter==='priya'?'P':'T'}</b></div><div class="worker worker-two"><i></i></div><div class="incident-ring"></div><div class="world-mood-tag">${moodLabel[w.people[chapter].mood]}</div><div class="world-board"><small>${monitor?'INDIVIDUAL FEED':'WORKFLOW VIEW'}</small><strong>${monitor?'PACE / LIVE':w.tReidLeak?'ROBOT 07 / LOADS':'TASKS / QUEUES'}</strong><i></i><i></i><i></i></div><div class="world-breakroom"><span>${w.tBreak?'BREAK / COVERED':'BREAK STATION'}</span><b>☕</b></div><div class="world-queue-crates">${'<i></i>'.repeat(w.queue)}</div><div class="world-office"><span>REVIEW DESK</span><b>${chapter==='tom'?(w.mRemedy?'HEARING OPEN':w.mAppeal?'IN REVIEW':'FILE WAITING'):chapter==='priya'?(w.pValidated?'EVENT CHECKED':w.pDiagnosis?'CHECK PENDING':'OPEN QUESTION'):'SHIFT OFFICE'}</b></div><div class="warehouse-corner">AN AUTHORED STORY WORLD</div></div>${interactive?`<div class="world-hotspots" aria-label="Inspect the warehouse"><button data-action="inspect" data-zone="floor">Picking floor ${arrow}</button><button data-action="inspect" data-zone="break">Break station ${arrow}</button><button data-action="inspect" data-zone="desk">Review desk ${arrow}</button></div>`:''}</div>`;
}
function home(){return `<main id="main" tabindex="-1"><section class="hero game-hero"><div><div class="eyebrow"><span></span> ONE WAREHOUSE. THREE WORKING LIVES.</div><h1>What happens<br>on <em>your shift?</em></h1><p class="hero-intro">A story you don’t just read.<br>A workplace you leave changed.</p><p class="hero-description">Take the manager’s desk. Plan the floor, follow the evidence, and decide who gets heard. Choices travel with you. The next shift inherits what you leave behind.</p><div class="hero-buttons"><button class="button primary" data-action="new" data-mode="campaign">Start a new campaign ${arrow}</button>${app.run?`<button class="button secondary" data-action="resume">Continue your shift ${arrow}</button>`:''}</div><div class="hero-meta"><span>3 connected chapters</span><span>20 endings to discover</span><span>A world that remembers</span></div></div><div class="hero-art">${warehouse(app.run?simulate(app.run).world:{tMonitor:'public',tQueue:'blocked',mCollect:false})}<div class="hero-caption"><span>YOUR DECISIONS REACH BEYOND THIS DESK</span><p>What will the next team<br>walk into?</p><span class="caption-mark" aria-hidden="true">?</span></div></div></section><section class="campaign-strip"><div><span class="eyebrow">THE CONNECTED CAMPAIGN</span><h2>Three people. One changing workplace.</h2></div><p>A missed break can close a conversation. A leaked report can silence a witness. A preserved file can reopen an appeal. The warehouse carries those changes from one chapter into the next.</p></section><section class="cases-section" aria-labelledby="cases-title"><div class="section-heading"><div><div class="eyebrow">PLAY A SINGLE CHAPTER</div><h2 id="cases-title">Whose shift will you enter?</h2></div><button class="text-link" data-action="endings">${app.discoveries.length} / 20 endings found ${arrow}</button></div><div class="case-grid">${chapters.map(s=>`<article class="case-card ${s.id}"><div class="case-card-top"><span>CHAPTER ${s.number}</span><span>Reactive story</span></div><div class="card-person">${portrait(s.id)}<div><span class="person-name">${s.person}</span><span class="person-role">${s.role}</span></div><span class="case-number" aria-hidden="true">${s.number}</span></div><div class="case-card-body"><div class="case-theme">${s.theme}</div><h3>${s.title}</h3><p>${s.hook}</p><button class="case-link" data-action="new" data-mode="${s.id}">Play ${s.person}’s chapter ${arrow}</button><span class="card-progress">Your world opens different follow-ups</span></div></article>`).join('')}</div></section><section class="experience-note"><span class="note-mark" aria-hidden="true">↶</span><div><h2>A different choice leaves a different world.</h2><p>Rewind a decision, rebuild the evidence packet, and find another ending. Your journal keeps the chain of events visible.</p></div><button class="text-link" data-action="how">Before you clock in ${arrow}</button></section><p class="method-note">Based on Team 12’s three CT3 scenarios and proposed AMR monitoring policy. People, records, planning slots, and outcomes are authored fiction. The floor animation illustrates the story and does not simulate robot physics.</p></main>`;}
function initDraft(s){return s.type==='allocation'?Object.fromEntries(s.items.map(i=>[i.id,0])):s.type==='records'?[]:null;}
function statePanel(ev){const l=worldLabels(ev.world,ev.chapter);return `<section class="world-state" aria-label="World state"><h3>The warehouse you’re shaping</h3><dl><div><dt>People</dt><dd>${esc(l.worker)}</dd></div><div><dt>Operations</dt><dd>${esc(l.operations)}</dd></div><div><dt>Records</dt><dd>${esc(l.data)}</dd></div></dl><p>Qualitative states in this fictional branch.</p></section>`;}
function notebook(ev){const e=ev.log.at(-1);return `<details class="policy-notebook"><summary>Policy notebook <span>${e?'Updated':'Reference'}</span></summary>${e?`<span class="policy-stamp ${e.policy}">${policyNames[e.policy]}</span><h3>${esc(e.question)}</h3><p>${esc(e.why)}</p>${e.tradeoff?`<p><strong>Tradeoff</strong><br>${esc(e.tradeoff)}</p>`:''}`:'<p>After a decision, its relationship to the team’s proposal appears here. Outcomes are authored examples, not a score of your ethics.</p>'}<button class="text-link" data-action="policy">Read the four rules ${arrow}</button></details>`;}
function journal(ev){return `<details class="journal-sidebar"><summary>Decision journal <span>${ev.log.length}</span></summary>${ev.log.length?ev.log.map((e,i)=>`<div class="mini-entry"><span class="policy-dot ${e.policy==='review'?'conditional':e.policy}"></span><div><strong>${i+1}. ${chapterById(e.chapter).person} / ${esc(e.question)}</strong><p>${esc(e.label)}</p><button data-action="rewind" data-index="${e.eventIndex}">Rewind to this decision</button></div></div>`).join(''):'<p class="muted">Your choices and their consequences will appear here.</p>'}</details>`;}
function preparation(ev){const w=ev.world,plan=w[ev.chapter==='tim'?'tPlan':ev.chapter==='priya'?'pPlan':'mPlan'];if(!plan)return '';const labels={coverage:'Break coverage',routing:'Queue coordination',mentoring:'Mentoring',alternate:'Alternate route',reviewer:'Request review',validation:'Validation',cover:'Work coverage',review:'Context review',training:'New-shift training'};return `<section class="prep-board"><h3>Your preparation board</h3>${Object.entries(plan).map(([key,n])=>`<div class="prep-row ${n?'':'unplanned'}"><span>${labels[key]}</span><b>${n?n+' planning '+(n===1?'slot':'slots'):'Reactive / not prepared'}</b></div>`).join('')}</section>`;}
function timeline(s,w){if(s.id!=='p-trace'||!w.pRobot||!w.pTrace)return '';return `<div class="event-timeline" aria-label="Synthetic event sequence"><div><time>13:14:06</time>Unloading in progress</div><div class="signal-event"><time>13:14:08</time>Completion received</div><div><time>13:14:09</time>Movement begins</div><div><time>13:14:10</time>Emergency stop</div></div>`;}
function choiceForm(s){
  if(s.id==='t-queue')return `<fieldset class="choices-field"><legend>Make the dispatch call</legend><div class="dispatch-map" aria-hidden="true"><span class="dispatch-zone">PICKING A</span><span class="dispatch-block">BLOCKED HANDOFF</span><span class="dispatch-end">PACKING B</span><svg viewBox="0 0 420 150"><path class="direct-path" d="M40 75H380"/><path class="detour-path" d="M40 75V25H380V75"/></svg><span class="dispatch-robot">AMR 01</span></div>${s.choices.map((c,i)=>`<label class="choice game-choice route-choice"><input type="radio" name="response" value="${c.id}" ${c.locked?"disabled":""} ${draft===c.id?'checked':''}><span class="choice-letter" aria-hidden="true">${i===0?'↗':i===1?'!':'…'}</span><span class="choice-copy"><strong>${c.label}</strong><span>${c.detail}</span>${c.locked?`<span class="locked-reason">${c.lockedReason}</span>`:""}</span></label>`).join('')}</fieldset>`;
  if(s.type==='allocation')return `<fieldset class="allocation-field"><legend>Assign up to three planning slots</legend><p class="slots-status" role="status" id="slots-status">${3-Object.values(draft).reduce((a,b)=>a+b,0)} slots remaining</p>${s.items.map(i=>`<label class="allocation-row"><span><strong>${i.label}</strong><small>${i.detail}</small></span><select aria-label="Planning slots for ${i.label}" data-slot="${i.id}">${[0,1,2,3].map(n=>`<option value="${n}" ${draft[i.id]===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<p class="microcopy">Assigning no slot leaves that preparation undone. Essential rights and justified review remain available.</p></fieldset>`;
  if(s.type==='records')return `<fieldset class="records-field"><legend>Choose ${s.min===s.max?s.min:s.min+'–'+s.max} record${s.max>1?'s':''}</legend><div class="evidence-cards">${s.records.map((r,i)=>`<label class="evidence-card ${draft.includes(r.id)?'selected':''}"><input type="checkbox" name="record" value="${r.id}" ${r.locked?"disabled":""} ${draft.includes(r.id)?'checked':''}><span class="record-index">FILE ${String(i+1).padStart(2,'0')}</span><strong>${r.label}</strong><span>${r.detail}</span>${r.locked?`<span class="locked-reason">${r.lockedReason}</span>`:""}<b class="record-check" aria-hidden="true">${draft.includes(r.id)?'✓':'+'}</b></label>`).join('')}</div><p id="record-status" class="microcopy" role="status">${draft.length} selected</p></fieldset>`;
  return `<fieldset class="choices-field"><legend>What do you do?</legend>${s.choices.map((c,i)=>`<label class="choice game-choice ${draft===c.id?'selected':''}"><input type="radio" name="response" value="${c.id}" ${c.locked?"disabled":""} ${draft===c.id?'checked':''}><span class="choice-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span class="choice-copy"><strong>${c.label}</strong><span>${c.detail}</span>${c.locked?`<span class="locked-reason">${c.lockedReason}</span>`:""}</span></label>`).join('')}</fieldset>`;
}
function play(){
  const ev=simulate(app.run),s=chapterById(ev.chapter);if(!app.run.revealed&&ev.stage!=='play')return endingPage(ev);
  const last=ev.log.at(-1),current=app.run.revealed?sceneById(last.id):ev.scene;if(draft===null&&!app.run.revealed)draft=initDraft(current);
  const actIndex=chapters.findIndex(c=>c.id===ev.chapter),n=ev.log.filter(e=>e.chapter===ev.chapter).length;
  return `<main id="main" class="game-main" tabindex="-1"><div class="case-breadcrumb"><button class="text-link" data-action="home">← Leave the desk</button><span>${app.run.mode==='campaign'?'CONNECTED CAMPAIGN':'SINGLE CHAPTER'} / ${s.person}</span><div class="case-clock">${s.time}<small>ILLUSTRATIVE SHIFT TIME</small></div></div><div class="case-heading"><div><div class="eyebrow">CHAPTER ${s.number} / ${s.theme}</div><h1>${s.title}</h1></div><button class="text-link" data-action="how">How to play ${arrow}</button></div><div class="chapter-track" aria-label="Campaign chapters">${chapters.map((c,i)=>`<span class="${i===actIndex?'active':i<actIndex&&app.run.mode==='campaign'?'done':''}"><b>${c.number}</b> ${c.person}<small>${i===actIndex?n+' decision'+(n===1?'':'s')+' made':c.theme}</small></span>`).join('')}</div>${liveStrip(ev.world,ev.chapter)}<div class="game-layout"><div class="desk-column">${app.run.revealed?`<section class="decision-panel event-panel"><div class="decision-kicker"><span>ON THE FLOOR</span><span>YOUR CHOICE HAS LANDED</span></div><h2>${esc(current.title)}</h2><div class="committed-slip"><span>YOUR DECISION</span><p>${esc(last.label)}</p></div><div class="world-event"><span class="eyebrow">ON THE FLOOR</span><p>${esc(last.event)}</p></div>${impactPanel(last,ev)}<div class="feedback-actions"><button class="text-link" data-action="rewind" data-index="${last.eventIndex}">Try a different decision ↶</button><button class="button primary" data-action="continue">${ev.stage==='play'?'Follow the story':ev.stage==='chapterEnd'?'See this chapter’s ending':'See the world you leave'} ${arrow}</button></div></section>`:`<section class="decision-panel"><div class="decision-kicker"><span>AT THE MANAGER’S DESK</span><span>DECISION ${n+1}</span></div><h2 id="decision-title">${esc(current.title)}</h2>${current.cause&&!current.cause.startsWith("The current world")?`<p class="scene-cause"><span>WHY THIS MOMENT EXISTS</span>${esc(current.cause)}</p>`:""}<p class="story-prompt">${esc(content(current.prompt,ev.world))}</p>${timeline(current,ev.world)}<form id="decision-form">${choiceForm(current)}<p class="form-error" id="form-error" role="alert">${esc(error)}</p><div class="commit-row"><span>${current.type==='records'?'Build your packet. Its contents change the investigation.':current.type==='allocation'?'The floor inherits your plan.':'No answer is selected for you.'}</span><button class="button primary" id="commit-button" type="submit" ${validAnswer(current,draft)?'':'disabled'}>Put it into motion ${arrow}</button></div></form></section>`}${notebook(ev)}<div class="desk-note">Decisions change an authored story. Open the policy notebook to examine the reasoning and its limits.</div></div><aside class="game-sidebar" aria-label="The living warehouse"><div class="world-title"><span class="eyebrow">THE FLOOR / NOW</span><span class="world-live">● Story state</span></div>${warehouse(ev.world,ev.chapter,true)}${crewRoster(ev.world,ev.chapter)}${reactionPanel(ev.world,ev.chapter)}<div class="worker-file compact-file"><div class="worker-file-top">${portrait(ev.chapter,'small')}<div><span class="file-label">THE PERSON IN THIS CHAPTER</span><strong>${s.person}</strong><span>${s.role}</span></div></div><p>${s.intro}</p></div>${statePanel(ev)}${preparation(ev)}${developing(ev.world)}${journal(ev)}</aside></div></main>`;
}
function characterLine(ev){const w=ev.world;return ev.chapter==='tim'?(w.tVoice?'Tim’s account is now part of the handover.':w.tBreak?'Tim is at the break station. The queue is still a management problem.':'Tim is watching what the shift rewards.'):ev.chapter==='priya'?(w.pHeard?'Priya has been able to finish her account.':w.pPace?'Priya’s report is now being used to question her output.':'Priya is waiting to learn what reporting the event will mean.'):w.mRemedy?'Tom has a route that can change the decision.':w.mAppeal?'Tom’s case is open. Whether it can change anything is still being decided.':'Tom is waiting for more than a precise-looking report.';}
function recordEnding(ev){
  if(app.run.revealed||ev.stage==='play')return;
  app.discoveries=[...new Set([...app.discoveries,...ev.chapterEndings.map(e=>e.id),ev.chapterEnding,ev.ending].filter(Boolean))];
  if(ev.stage==='ending'&&!app.archive.some(r=>r.id===app.run.id&&JSON.stringify(r.events)===JSON.stringify(app.run.events))){app.archive.push(structuredClone(app.run));app.archive=app.archive.slice(-12);}save();
}
function endingPage(ev){
  recordEnding(ev);
  const story=endingStory(app.run),campaign=app.run.mode==='campaign'&&ev.stage==='ending';
  const prev=app.archive.filter(r=>r.mode===app.run.mode&&JSON.stringify(r.events)!==JSON.stringify(app.run.events)).at(-1);
  return `<main id="main" class="results-main game-ending v4-ending" tabindex="-1"><div class="case-breadcrumb"><button class="text-link" data-action="home">← Back to the entrance</button><button class="text-link" data-action="endings">Ending collection ${arrow}</button></div><div class="ending-layout"><section><div class="eyebrow">${campaign?'TOMORROW, IN THIS WAREHOUSE':chapterById(ev.chapter).person.toUpperCase()+' / AFTER THE SHIFT'}</div><div class="ending-number">${esc(story.id.toUpperCase())} / DISCOVERED</div><h1>${esc(story.title)}</h1><div class="ending-story vignette-story">${story.paragraphs.map((p,i)=>`<p>${campaign&&i<3?`<span class="story-byline">${chapters[i].person}</span>`:''}${esc(p)}</p>`).join('')}</div><div class="ending-reflection"><span class="eyebrow">THE STORY’S OPEN QUESTION</span><p>Which part of this workplace will hold when the next manager arrives? The notebook and journal let you examine the assumptions behind this fictional ending.</p></div><div class="next-buttons">${ev.stage==='chapterEnd'?`<button class="button primary" data-action="next-chapter">Continue to ${chapters[chapters.findIndex(c=>c.id===ev.chapter)+1].person} ${arrow}</button>`:`<button class="button primary" data-action="new" data-mode="${app.run.mode}">Find another future ${arrow}</button>`}<button class="button secondary" data-action="download">Take your shift journal ↓</button></div></section><aside>${warehouse(ev.world,ev.chapter,true)}${crewRoster(ev.world,ev.chapter)}${reactionPanel(ev.world,ev.chapter)}${statePanel(ev)}<div class="ending-postcard"><span class="eyebrow">THE WAREHOUSE AT HANDOVER</span>${signals(ev.world,ev.chapter).map(m=>`<div class="closing-signal"><span>${m.label}</span><strong>${esc(m.value)}</strong></div>`).join('')}<span>${app.discoveries.length} / 20 endings found</span></div>${prev?`<section class="route-comparison"><span class="eyebrow">ANOTHER WORLD YOU REACHED</span><h3>${esc(endingTitle(simulate(prev).ending))}</h3><p>${compareWorlds(prev,app.run)}</p></section>`:''}</aside></div><details class="ending-journal"><summary>Open your decision journal <span>${ev.log.length} decisions</span></summary><section class="review-journal"><div class="section-heading"><h2>The record behind the story</h2><button class="text-link" data-action="download">Download journal ↓</button></div>${ev.log.map((e,i)=>`<article class="review-entry"><span class="entry-number">${String(i+1).padStart(2,'0')}</span><div><span class="policy-stamp ${e.policy}">${policyNames[e.policy]}</span><h3>${chapterById(e.chapter).person} / ${esc(e.question)}</h3><p class="review-choice">${esc(e.label)}</p><p>${esc(e.event)}</p><details><summary>Why this policy assessment?</summary><p>${esc(e.why)}</p>${e.tradeoff?`<p>${esc(e.tradeoff)}</p>`:''}</details></div><button class="text-link" data-action="rewind" data-index="${e.eventIndex}">Rewind ↶</button></article>`).join('')}</section></details><p class="method-note">These people, emotions, operational pressures, and outcomes are authored story states. They illustrate the team’s proposal without predicting real worker reactions or robot performance.</p></main>`;
}
function compareWorlds(a,b){const av=simulate(a),bv=simulate(b),old=signals(av.world,av.chapter),now=signals(bv.world,bv.chapter);const diffs=now.map((m,i)=>m.value!==old[i].value?`${m.label} was “${old[i].value}” in that world and is “${m.value}” here.`:'').filter(Boolean);return esc(diffs.slice(0,3).join(' ')||'The visible conditions are similar, but the warehouse may have reached them through a different history. The journal retains that history.');}
function collection(){return `<main id="main" class="collection-main" tabindex="-1"><div class="eyebrow">THE ENDING COLLECTION</div><h1>Other ways<br>the shift <em>could end.</em></h1><p class="collection-intro">${app.discoveries.length} of 20 discovered in this browser. Titles stay covered until you reach them. A different ending is a different problem to examine, not an ethical trophy.</p>${Object.entries(endingCatalog).map(([mode,list])=>`<section class="ending-shelf"><div class="section-heading"><h2>${mode==='campaign'?'The whole warehouse':chapterById(mode).person+'’s chapter'}</h2><button class="text-link" data-action="new" data-mode="${mode}">Play ${arrow}</button></div><div class="ending-grid">${list.map(([id,title],i)=>`<article class="ending-card ${app.discoveries.includes(id)?'found':'locked'}"><span>${String(i+1).padStart(2,'0')} / ${app.discoveries.includes(id)?'DISCOVERED':'UNEXPLORED'}</span><h3>${app.discoveries.includes(id)?title:'A shift you haven’t seen'}</h3><p>${app.discoveries.includes(id)?'Try another route to explore what changes.':'Your choices will reveal this story.'}</p></article>`).join('')}</div></section>`).join('')}<button class="button secondary" data-action="home">Return to the entrance ${arrow}</button></main>`;}
function render(focus=true){root.innerHTML=header()+(screen==='home'?home():screen==='collection'?collection():app.run?play():home())+footer();if(focus){document.querySelector('#main')?.focus();window.scrollTo({top:0,behavior:'instant'});}}
function showDialog(title,body){document.querySelector('#dialog-content').innerHTML=`<div class="eyebrow">THE NEXT SHIFT / FIELD NOTES</div><h2 id="dialog-title">${title}</h2>${body}`;dialog.showModal();}
function start(mode){app.run=freshRun(mode);draft=null;error='';screen='game';save();render();}
function inspect(zone){
  const ev=simulate(app.run),w=ev.world;
  const texts={floor:ev.chapter==='tim'?(w.tQueue==='managed'?'The route detours around the blocked handoff. Current assignments can coordinate that work without saving an individual output history.':w.tTaskBlind?'Dispatch cannot see the active-task links. The proposal allows minimum information necessary for that coordination.':'A blocked handoff can lower a pick count without saying anything about a worker’s effort. The output alone leaves that context out.'):ev.chapter==='priya'?(w.pDiagnosis?'The synthetic event packet points to a premature completion-message sequence. A technical team still needs to validate any diagnosis.':'A completion signal arrived before unloading finished. A worker’s whole-day pace does not explain which signal generated this event.'):'The same output count can include difficult assignments, training, and waiting. A fair review needs to examine the inference being made.',break:w.tBreak?'A worker can reach the break station. Whether that is supported by coverage, task reassignment, or a later repair is recorded in your journal.':'Break protection and workload remain organizational questions. Turning off a leaderboard alone does not answer them.',desk:ev.chapter==='priya'?(w.pBroad||w.pPurposeBreach?'The incident record has exceeded its current purpose boundary. A later restriction cannot undo an earlier disclosure.':'The review desk should ask which specific safety question remains unresolved, what non-identifying checks were made, and why each additional field is necessary.'):ev.chapter==='tom'?(w.mAuthority?'A separate reviewer can change an unsupported decision. That authority matters as much as holding the meeting.':'A reviewer who can only repeat or recommend a conclusion may not provide a meaningful remedy.'):(w.tReidLeak?'Robot 07’s whole-shift count can be linked to its worker even when employee IDs are hidden.':'Check linked exports and what a supervisor already knows. A name-free view is not automatically non-identifying.')};
  showDialog(zone==='floor'?'At the picking floor':zone==='break'?'At the break station':'At the review desk',`<p>${texts[zone]}</p><p class="dialog-callout">Inspecting the floor provides context. Your world changes when you commit a decision at the desk.</p>`);
}
root.addEventListener('change',e=>{
  if(screen!=='game'||!app.run||app.run.revealed)return;const s=simulate(app.run).scene;if(!s)return;
  if(e.target.matches('[data-slot]')){draft[e.target.dataset.slot]=Number(e.target.value);const left=3-Object.values(draft).reduce((a,b)=>a+b,0);document.querySelector('#slots-status').textContent=left>=0?`${left} slots remaining`:`${-left} over the limit. Reassign a slot.`;}
  else if(e.target.name==='record'){draft=Array.from(root.querySelectorAll('input[name="record"]:checked')).map(n=>n.value);root.querySelectorAll('.evidence-card').forEach(label=>{const checked=label.querySelector('input').checked;label.classList.toggle('selected',checked);label.querySelector('.record-check').textContent=checked?'✓':'+';});document.querySelector('#record-status').textContent=`${draft.length} selected${draft.length>s.max?'. Remove a record to continue.':''}`;}
  else if(e.target.name==='response'){draft=e.target.value;root.querySelectorAll('.game-choice').forEach(label=>label.classList.toggle('selected',label.querySelector('input').checked));}
  document.querySelector('#commit-button').disabled=!validAnswer(s,draft);document.querySelector('#form-error').textContent='';
});
root.addEventListener('submit',e=>{if(e.target.id!=='decision-form')return;e.preventDefault();try{app.run=commit(app.run,draft);draft=null;error='';save();render();}catch(err){error=err.message;document.querySelector('#form-error').textContent=error;}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset);});
dialog.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset);});
function act(action,data={}){
  if(action==='close-dialog'){dialog.close();return;}
  if(action==='home'){screen='home';draft=null;render();return;}
  if(action==='resume'){screen='game';draft=null;render();return;}
  if(action==='endings'){screen='collection';render();return;}
  if(action==='new'){const ev=app.run?simulate(app.run):null;if(app.run&&ev.stage!=='ending'&&app.run.events.length){showDialog('Leave this route?',`<p>A new run replaces the current route. Discovered endings and completed routes stay in this browser. You can download your current journal first.</p><div class="modal-actions"><button class="button secondary" data-action="download">Download current journal</button><button class="button primary" data-action="start-confirm" data-mode="${data.mode}">Start the new route</button></div>`);}else start(data.mode);return;}
  if(action==='start-confirm'){dialog.close();start(data.mode);return;}
  if(action==='continue'){app.run=continueRun(app.run);draft=null;save();render();return;}
  if(action==='next-chapter'){app.run=advanceChapter(app.run);draft=null;save();render();return;}
  if(action==='person'){const ev=simulate(app.run),id=data.person,p=ev.world.people[id];showDialog(chapterById(id).person+' / '+moodLabel[p.mood],`<p class="person-dialog-quote">${esc(p.quote)}</p><p class="dialog-callout">This is the character’s current authored reaction. Earlier shifts can leave it in place while another person’s chapter unfolds.</p>`);return;}
  if(action==='inspect'){inspect(data.zone);return;}
  if(action==='rewind'){rewindTarget=Number(data.index);showDialog('Change the turning point?',`<p>Rewinding clears this decision and every decision after it, including later chapters in a campaign. Your discovered endings and completed-route archive remain available.</p><div class="modal-actions"><button class="button secondary" data-action="close-dialog">Keep this route</button><button class="button primary" data-action="rewind-confirm">Rewind this decision</button></div>`);return;}
  if(action==='rewind-confirm'){app.run=rewind(app.run,rewindTarget);draft=null;screen='game';dialog.close();save();render();return;}
  if(action==='download'){if(!app.run)return;const url=URL.createObjectURL(new Blob([exportJournal(app.run)],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='The-Next-Shift-v4-Journal.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==='reset'){showDialog('Start with a clean desk?',`<p>This clears only v4’s current route, completed-route archive, and ending collection in this browser. Download your journal first if you want to keep it.</p><div class="modal-actions">${app.run?'<button class="button secondary" data-action="download">Download current journal</button>':''}<button class="button primary" data-action="reset-confirm">Clear this v4 game</button></div>`);return;}
  if(action==='reset-confirm'){app=initialApp();screen='home';draft=null;dialog.close();save();render();return;}
  if(action==='how'){showDialog('Before you clock in',`<ol class="how-list"><li><strong>Choose your shift.</strong><p>Play the connected campaign or enter one person’s chapter. Campaign decisions carry into later chapters.</p></li><li><strong>Work at the desk.</strong><p>Assign three fictional planning slots, assemble evidence packets, make access decisions, and respond to workers. No answer is preselected.</p></li><li><strong>Watch the floor change.</strong><p>The world strip shows mood, willingness to speak, queue pressure, data boundaries, and evidence. Immediate reactions and delayed ripples change later scenes. A sealed record explains why it is unavailable. There are no real-time penalties for reading slowly.</p></li><li><strong>Reach an ending and question it.</strong><p>Each chapter has four endings. The whole campaign has eight. The ending follows people through the resulting workplace. The separate journal preserves your choices for review.</p></li><li><strong>Try a different turning point.</strong><p>Rewind from the journal, compare with a previous route, or start again. Saved progress stays in this browser.</p></li></ol><p class="dialog-callout">This is an authored educational game. Planning slots and qualitative world states do not measure worker health, productivity, or real policy effectiveness. The notebook assesses choices against Team 12’s proposal. Character moods are authored possibilities, not guaranteed or measured human reactions.</p>`);return;}
  if(action==='policy'){showDialog('The boundary you are testing',`<ol class="policy-rules"><li><strong>Prohibit continuous individual productivity monitoring.</strong><p>AMR, fleet, and linked-system data must not build ongoing productivity records about identifiable workers.</p></li><li><strong>Permit necessary operations and aggregate analysis.</strong><p>Navigation, collision avoidance, safe stopping, and the minimum worker information needed for an active task remain permitted. Test whether a summary can still identify a worker.</p></li><li><strong>Limit identifiable access to a specific safety incident.</strong><p>After a documented collision, injury, or credible near miss, start with non-identifying records. A designated reviewer may authorize only the minimum identifiable information needed for a specific unresolved safety question.</p></li><li><strong>Require notice, access controls, and remedies.</strong><p>Explain collection, purposes, recipients, and retention. Operations managers receive aggregate views. Workers need a way to challenge misuse.</p></li></ol><h3>What the game adds</h3><p>The request gate, contextual re-identification test, separate review, bounded dispute preservation, and planning dilemmas explore possible safeguards. They are proposed implementations and tradeoffs for the team to assess, not additional rules already established by the presentation.</p>`);return;}
  if(action==='sources'){showDialog('The source of this world',`<p>Tim, Priya, and Tom come from Team 12’s CT3 presentation. The monitoring boundary comes from the Project Scope & Team Charter and the presentation’s four-part alignment strategy.</p><h3>Reactive story states</h3><p>Character mood, willingness to speak, queue pressure, record access, and evidence feed later branches. These are discrete fictional states. They do not measure health or policy effectiveness.</p><h3>Authored extensions</h3><p>Bamazon, records, dialogue, event sequences, planning slots, branches, and endings are fictional. In particular, the premature-message diagnosis is a synthetic extension for exploring an event-specific investigation. It is not a claim about a real vendor or a physical repair instruction.</p><h3>What you can evaluate</h3><p>Whether visitors can distinguish necessary operations, identifiable productivity histories, a justified safety exception, and meaningful review. Visitors can also challenge whether the game’s authored consequences are persuasive. A favorable ending does not prove the policy works in practice.</p><h3>Privacy and scope</h3><p>There are no visitor accounts, analytics, real worker records, or response uploads. Progress is saved in this browser under a separate v4 key. Downloading a journal creates a local text file. The warehouse illustration is not a physically accurate robot simulation.</p><h3>Local project sources</h3><ul class="source-links"><li>Team 12 — Project Scope & Team Charter, project scope and synthetic-data restrictions.</li><li>CT3 — Senario, Tim, Priya, Tom, and the four alignment rules.</li><li>Team 12 cross-examination, the unresolved-question gate and indirect worker identification objections.</li></ul>`);}
}
render(false);
